"""Most frequent words in a text: "b a b c a b" -> [("b", 3), ("a", 2)] with k=2."""
import re
from collections import Counter


def top_words(text, k):
    """The k most frequent words as (word, count), highest count first, ties in alphabetical order.

    Text is lower-cased first; a word is a maximal run of a-z, so every other character separates words.
    Returns fewer than k pairs when there are fewer distinct words. k must be an int >= 1.
    """
    if k < 1:
        raise ValueError(f"k must be at least 1: {k!r}")
    counts = Counter(re.findall(r"[a-z]+", text.lower()))
    return sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))[:k]
