def wrap(text, width):
    """Wrap text to lines of at most width characters, one or more blank lines between paragraphs.

    Inside a paragraph all whitespace collapses to single spaces, then words are filled greedily.
    A word longer than width gets a line of its own, unbroken. Paragraphs are separated by exactly
    one empty line, and the result has no trailing newline. Raises ValueError if width < 1.
    """
    if width < 1:
        raise ValueError(f"width must be at least 1: {width!r}")
    paragraphs = []
    words = []
    for line in text.splitlines():
        found = line.split()
        if found:
            words.extend(found)
        elif words:
            paragraphs.append(words)
            words = []
    if words:
        paragraphs.append(words)

    out = []
    for para in paragraphs:
        if out:
            out.append("")
        cur = ""
        for word in para:
            if cur and len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                if cur:
                    out.append(cur)
                cur = word
            if len(cur) > width:
                # Too long to share a line: it stands alone and is never split.
                out.append(cur)
                cur = ""
        if cur:
            out.append(cur)
    return "\n".join(out)

