            else:
                if cur:
                    out.append(cur)
                cur = word
            if len(cur) > width:
                # Too long to share a line: it stands alone and is never split.
                out.append(cur)
                cur = ""
        if cur:
            out.append(cur)
    return "\n".join(out)

